import itertools
import json

# Semantic adjective classes, including the adjectives appearing in the options.
classes = {
    "opinion": """
        lovely silly good wonderful awful terrible ridiculous mysterious
        repulsive nice
    """.split(),
    "size": """
        huge medium-size normal-size large massive tiny midsize enormous small
    """.split(),
    "age": """
        ancient new old-fashioned archaic old brand-new
    """.split(),
    "shape": """
        rectangular spherical prismlike circular square triangular pyramidal
    """.split(),
    "color": """
        maroon pink blue cyan black magenta brown white gray teal crimson violet
        green yellow indigo
    """.split(),
    "origin": """
        russian thai vietnamese bangladeshi brazilian mexican egyptian chinese
        american pakistani japanese iranian nigerian filipino indian turkish
        german ethiopian
    """.split(),
    "material": """
        paper fiberglass glass wool cloth leather wood rubber iron cardboard
        canvas plastic steel
    """.split(),
    "purpose": """
        hiking driving walking drinking exercise smoking typing eating snorkeling
        whittling
    """.split(),
}

category = {
    word: name
    for name, words in classes.items()
    for word in words
}

# Original examples. Single-adjective examples establish vocabulary but
# impose no precedence constraint.
givens = """
lovely canvas; huge box; silly calculator; paper ancient bag;
russian marker; new bottle; thai table; rectangular necklace;
old-fashioned jar; vietnamese marker; bangladeshi spherical spoon;
spherical necklace; fiberglass house; brazilian stapler; new cup;
glass archaic screwdriver; maroon good bottle; mexican prismlike ball;
medium-size hiking plate; egyptian prismlike watch; driving speaker;
circular ruler; chinese sofa; awful bed; old bed; huge hammer;
vietnamese prismlike shirt; american hammer; square bicycle;
wool ancient shoe; pink car key; american spherical bag;
brazilian triangular trash can; pyramidal brush; glass ancient bottle;
mexican spherical clock; square spoon; good scissors; cloth earring;
triangular large new house; pakistani rectangular screwdriver;
japanese dog; prismlike watch; russian circular banana; blue umbrella;
normal-size marker; leather ancient knife; new earring;
blue wonderful clock; thai pyramidal stapler; wood archaic piano;
rubber trash can; brand-new hat; ancient clock; triangular guitar;
iranian box; large pen; normal-size walking shirt; nigerian square fork;
iranian triangular bed; cyan hat; wonderful shirt; drinking sunglasses;
glass necklace; russian fire extinguisher; cyan wallet; nigerian spoon;
old-fashioned pencil; cyan shirt; black silly trash can;
magenta terrible apple; chinese rectangular jar; magenta lamp;
new table; new jar; old-fashioned key; archaic ball; large speaker;
brown stapler; walking shirt; medium-size speaker; prismlike wallet;
glass brand-new bed; terrible dog; ridiculous drill; tiny lamp;
white mysterious fire extinguisher; iranian necklace;
leather archaic clock; iranian chair; rubber wallet; square marker;
glass old box; white brush; walking chair; circular chair; maroon vase;
iranian triangular hammer; nice candle; massive sofa;
white repulsive calculator; paper sofa; terrible ball; terrible bag;
drinking spoon; archaic plate; pyramidal toolbox; blue awful clock;
wonderful scissors; vietnamese square wrench; midsize guitar;
silly necklace; leather box; filipino spherical spoon; new ball;
spherical ring; exercise sunglasses; driving earring; smoking drill;
indian pyramidal bottle; triangular flower pot; turkish speaker;
fiberglass pen; leather old-fashioned wallet; midsize driving speaker;
leather archaic spoon; paper archaic sunglasses;
american triangular shirt; brand-new camera; awful jar;
vietnamese calculator; tiny bicycle; gray silly bottle; gray clock;
teal ball; typing pencil; iron necklace; eating table; rectangular piano;
large typing earring; leather flower pot; circular camera;
old-fashioned shirt; wood ancient ball; american key; crimson bicycle;
german prismlike spoon; pyramidal stapler; ancient wrench;
crimson lovely ball; cloth archaic stapler; egyptian necklace;
ethiopian pyramidal canvas; massive bottle; violet good bag;
brand-new speaker; cloth old candle; spherical book; wonderful ring;
bangladeshi earring; german screwdriver; walking bottle;
crimson nice guitar; crimson lovely speaker; paper chair;
enormous earring; eating banana; german rectangular bird; typing cup;
tiny dog; black repulsive apple; green candle; driving bowl;
normal-size spoon; iranian eating glass screwdriver;
american spherical hammer; triangular drill; wonderful bottle;
good bag; cyan guitar; circular sofa; turkish triangular earring;
lovely ruler; tiny snorkeling book; huge book; turkish rectangular wrench;
nigerian earring; midsize ruler; indian plier; old bowl;
violet nice sunglasses; awful necklace; wood bag; walking knife;
terrible sunglasses; cloth old trash can; paper old fire extinguisher;
medium-size snorkeling shirt; tiny typing spoon; good calculator;
archaic wrench; cardboard camera; walking brush; rubber lamp
"""

options = {
    "A": "massive hiking wool old-fashioned green silly marker",
    "B": "repulsive midsize typing plastic brand-new pyramidal ethiopian sofa",
    "C": "ethiopian rectangular medium-size driving glass ancient repulsive wallet",
    "D": "turkish circular massive whittling cardboard old yellow lovely fork",
    "E": "japanese prismlike small eating paper old-fashioned indigo table",
    "F": "massive typing paper old-fashioned ridiculous gray bottle",
    "G": "pyramidal medium-size drinking steel new pink ridiculous fire extinguisher",
    "H": "violet lovely enormous hiking leather new triangular wallet",
    "I": "terrible brown normal-size typing glass old triangular japanese necklace",
    "J": "bangladeshi prismlike huge drinking wood ancient umbrella",
}


def adjective_classes(sentence):
    result = []
    for word in sentence.split():
        if word not in category:
            break
        result.append(category[word])
    return result


def precedence_pairs(sequence):
    return {
        (sequence[i], sequence[j])
        for i in range(len(sequence))
        for j in range(i + 1, len(sequence))
        if sequence[i] != sequence[j]
    }


def main():
    examples = [s.strip() for s in givens.split(";") if s.strip()]
    if len(examples) != 204:
        print("UNSUPPORTED")
        return

    constraints = set()
    for sentence in examples:
        constraints.update(precedence_pairs(adjective_classes(sentence)))

    # Exhaustively enumerate every class order satisfying the original givens.
    admissible = []
    for permutation in itertools.permutations(classes):
        rank = {name: i for i, name in enumerate(permutation)}
        if all(rank[a] < rank[b] for a, b in constraints):
            admissible.append(rank)

    if not admissible:
        print("UNSUPPORTED")
        return

    # An option has correct order precisely when its additional precedence
    # constraints remain compatible with those established by the examples.
    counts = {}
    for label, sentence in options.items():
        pairs = precedence_pairs(adjective_classes(sentence))
        counts[label] = sum(
            all(rank[a] < rank[b] for a, b in pairs)
            for rank in admissible
        )

    answer = "".join(label for label in options if counts[label]) or "K"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "given_sentences": len(examples),
            "precedence_constraints": [
                list(pair) for pair in sorted(constraints)
            ],
            "admissible_class_orders": len(admissible),
            "compatible_orders_per_option": counts,
        },
    }, separators=(",", ":")))


main()
```
